      SEQ_LENGTH, (index) => index); // sequence of integers 0 to SEQ_LENGTH

  List<int> prevSortedSub = [];
  List<int> sortedSub = [];

  for (var i = 0; i <= SEQ_LENGTH - SUB_LENGTH; i++) {
    if (prevSortedSub.isEmpty) {
// get first subsequence of length SUB_LENGTH
      final sub = s.sublist(i, i + SUB_LENGTH);
      prevSortedSub = sub.toList()..sort(); // sort subsequence
    }

    for (var j = i + 1; j <= SEQ_LENGTH - SUB_LENGTH + 1; j++) {
// use next subsequence of length SUB_LENGTH from previous iteration
      sortedSub = prevSortedSub;

// get next subsequence of length SUB_LENGTH
      final nextSub = s.sublist(j, j + SUB_LENGTH);
