u16 checksum(UDPPacket *packet)
{
u16 *bytes = (u16 )packet;
u32 sum = 0;
for (int i = 0; i < packet->header.len; i += 2)
{
sum += bytes[i];
u16 carry = (sum >> 16) & 1;
sum = (sum & 0xffff) + carry;
}
